inline const PreviewChoices* ChoicesFor(uint32_t id){size_t lo=0,hi=sizeof(kPreviewChoices)/sizeof(kPreviewChoices[0]);while(lo<hi){size_t mid=(lo+hi)/2;if(kPreviewChoices[mid].outer<id)lo=mid+1;else hi=mid;}return lo<sizeof(kPreviewChoices)/sizeof(kPreviewChoices[0])&&kPreviewChoices[lo].outer==id?&kPreviewChoices[lo]:nullptr;}
inline uint32_t CycleChoice(uint32_t index,uint32_t count,bool next){return count?(next?(index+1)%count:(index?index-1:count-1)):0;}
